items.text:
set hfile [ replace_extension $filename "java" ]
set fhandle [ open_output_file $hfile ]

catch {
	p.print_to_file $fhandle $functions \
		$header $class $class_name
} error_message

catch { close $fhandle }

set keywords { 
	public private protected
	override abstract static
	method ctr
}

array set props { 
	access none 
	dispatch normal
	type method
}
set error_message ""
set parameters {}
set returns ""
set throws {}
set type "method"
